WITH cse_selector_3ea73066c075 AS MATERIALIZED (
SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
    SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({cse_selector_3ea73066c075_offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({cse_selector_3ea73066c075_start_ms:Int64}, {cse_selector_3ea73066c075_end_ms:Int64} + {cse_selector_3ea73066c075_step_ms:Int64}, {cse_selector_3ea73066c075_step_ms:Int64}))) AS eval_ts FROM (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {cse_selector_3ea73066c075_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_end_ms:Int64})
    ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
        SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_end_ms:Int64}) AND id IN (SELECT id FROM (SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {cse_selector_3ea73066c075_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({cse_selector_3ea73066c075_required_end_ms:Int64})) AS matched_series_ids)
    ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({cse_selector_3ea73066c075_offset_ms:Int64} + {cse_selector_3ea73066c075_lookback_ms:Int64}) AND NOT isNaN(value)
) GROUP BY tags ORDER BY tags
)
SELECT result_tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT result_tags AS result_tags, timestamp AS timestamp, any(value) AS value FROM (SELECT arrayFilter(tag -> tag.1 != '__name__', lhs.original_group) AS result_tags, lhs.timestamp AS timestamp, toFloat64(if((lhs.value = rhs.value), 1, 0)) AS value FROM (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, any(value) AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, time_series AS time_series FROM cse_selector_3ea73066c075
) ARRAY JOIN time_series AS point) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)), timestamp HAVING throwIf(count() > 1, 'found duplicate series for the match group on the lhs hand-side of the operation') = 0) AS lhs INNER JOIN (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, any(value) AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, time_series AS time_series FROM cse_selector_3ea73066c075
) ARRAY JOIN time_series AS point) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)), timestamp HAVING throwIf(count() > 1, 'found duplicate series for the match group on the rhs hand-side of the operation') = 0) AS rhs ON lhs.join_group = rhs.join_group AND lhs.timestamp = rhs.timestamp) GROUP BY result_tags, timestamp HAVING throwIf(count() > 1, 'multiple matches for labels: grouping labels must ensure unique matches') = 0) GROUP BY result_tags ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1, enable_global_with_statement = 1, enable_materialized_cte = 1
FORMAT JSONEachRow
